import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class AccountLookupServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AccountLookupServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String accountId = req.getParameter("id");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");

        // Basic input validation
        if (accountId == null || !accountId.matches("[0-9A-Za-z\\-]{1,36}")) {
            resp.sendError(400, "Invalid account ID format");
            return;
        }

        // Whitelist sort columns
        String safeSortCol = "created_at";
        if (sortCol != null) {
            switch (sortCol) {
                case "name": safeSortCol = "display_name"; break;
                case "balance": safeSortCol = "balance"; break;
                case "created": safeSortCol = "created_at"; break;
                case "status": safeSortCol = "account_status"; break;
                default: safeSortCol = "created_at";
            }
        }

        // Direction handling - developer assumed only ASC/DESC possible
        // but does not properly validate
        String safeDir = "ASC";
        if (direction != null && direction.length() < 120) {
            // "Sanitize" by removing obvious keywords
            String cleaned = direction.replaceAll("(?i)(drop|alter|truncate|insert|update|delete)", "");
            if (cleaned.equalsIgnoreCase("DESC") || cleaned.equalsIgnoreCase("ASC")) {
                safeDir = cleaned.toUpperCase();
            } else {
                // Developer thought this was safe since it's "just ordering"
                safeDir = cleaned;
            }
        }

        String query = "SELECT account_id, display_name, balance, account_status, created_at " +
                       "FROM accounts WHERE account_id = ? ORDER BY " + safeSortCol + " " + safeDir;

        log.info("Executing lookup for account: " + accountId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(query)) {

            ps.setString(1, accountId);
            ResultSet rs = ps.executeQuery();

            resp.setContentType("application/json");
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            while (rs.next()) {
                if (!first) sb.append(",");
                sb.append(String.format(
                    "{\"id\":\"%s\",\"name\":\"%s\",\"balance\":%s,\"status\":\"%s\",\"created\":\"%s\"}",
                    rs.getString("account_id"),
                    rs.getString("display_name"),
                    rs.getBigDecimal("balance"),
                    rs.getString("account_status"),
                    rs.getTimestamp("created_at")
                ));
                first = false;
            }
            sb.append("]");
            resp.getWriter().write(sb.toString());

        } catch (SQLException e) {
            log.warning("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
